from dateutil.parser import parse as parse_date
from taf.analyzer.base import LogReader
import re
from .netconf_log_entry import Direction, NetconfLogEntry
from .netconf_message import HelloRequest, HelloReply, RpcRequest, RpcReply, Notification


class NetconfLogReader(LogReader):
    _message_types = {
        (Direction.sent, b"hello"): HelloRequest,
        (Direction.received, b"hello"): HelloReply,
        (Direction.sent, b"rpc"): RpcRequest,
        (Direction.received, b"rpc-reply"): RpcReply,
        (Direction.received, b"notification"): Notification}

    _directions = {
        b"Received": Direction.received,
        b"Sending": Direction.sent}

    _timestamp_regex = re.compile(br'(\S+)')
    _message_regex = re.compile(br"(Sending|Received) message:(.*)")
    _message_type_regex = re.compile(br".*<(rpc-reply|notification|hello) ")

    def __init__(self, **kwargs):
        super(NetconfLogReader, self).__init__(**kwargs)
        self._request_parts = None

    def __iter__(self):
        """
        Iterate through log entries.

        :return: yield next NetconfLogEntry
        """
        request_parts = []
        for line in self._file_obj:
            result = self._process_line(line, request_parts)
            if result:
                yield result

    def _process_line(self, line, request_parts):
        timestamp = parse_date(self._timestamp_regex.match(line).group(1))
        match = self._message_regex.search(line)
        if match:
            direction_bytes, message_string = match.groups()
            direction = self._directions[direction_bytes]
            if direction == Direction.sent:
                return self._process_sent_message(timestamp, direction, message_string, request_parts)
            elif direction == Direction.received:
                return self._process_received_message(timestamp, direction, message_string)

    def _process_sent_message(self, timestamp, direction, message_string, request_parts):
        if message_string.startswith(b"<hello "):
            return self._create_netconf_log_entry(
                timestamp=timestamp,
                direction=direction,
                message_type=b"hello",
                message_string=message_string)
        if message_string.startswith(b"<rpc "):
            self._request_parts = [message_string]
        elif not re.match(rb"#(?:\d+|#)$", message_string):
            self._request_parts.append(message_string)
        if message_string.strip().endswith(b"</rpc>"):
            return self._create_netconf_log_entry(
                timestamp=timestamp,
                direction=direction,
                message_type=b"rpc",
                message_string=b"".join(self._request_parts))

    def _process_received_message(self, timestamp, direction, message_string):
        return self._create_netconf_log_entry(
            timestamp=timestamp,
            direction=direction,
            message_type=self._message_type_regex.match(message_string).group(1),
            message_string=message_string)

    def _create_netconf_log_entry(
            self,
            timestamp,
            direction,
            message_type,
            message_string):
        """
        Create a NETCONF log entry.

        :param datetime.datetime timestamp: timestamp of log entry
        :param Direction direction: sent or received
        :param bytes message_type: "hello", "rpc", "rpc-reply" or "notification"
        :param bytes message_string: NETCONF message as XML encoded string
        :return: NETCONF log entry
        :rtype: NetconfLogEntry
        """
        message_class = self._message_types[direction, message_type]
        return NetconfLogEntry(
            timestamp=timestamp,
            message=message_class(
                string=message_string))
